def handle_object_impact(
    self, obj: object
) -> tuple[
    str | None, str, str | None,
    list[dict[str, object]], dict[str, object] | None,
    dict[str, object] | None, dict[str, object] | None,
    dict[str, object] | None, dict[str, object] | None,
]:
    """Like :meth:`handle_object_reconciliation`, additionally returning
    the impact analysis of an ``IMPACT_REPORT`` query (``None``
    otherwise)."""
    if not isinstance(obj, dict):
        return None, REJECTED, INVALID_SCHEMA, [], None, None, None, None, None

    event_id = obj.get("event_id")
    event_id_out = event_id if isinstance(event_id, str) else None

    schema_error = self._schema_error(obj)
    if schema_error is not None:
        return event_id_out, REJECTED, schema_error, [], None, None, None, None, None

    if event_id in self._event_ids:
        return event_id, REJECTED, DUPLICATE_EVENT_ID, [], None, None, None, None, None
    if obj["type"] == REPLACE and "display_quantity" in obj:
        target = self._orders.get(obj["order_id"])
        if (
            target is not None
            and target["status"] == RESTING
            and "display_quantity" not in target
        ):
            # Only an iceberg target may be replaced with a display slice;
            # like every schema error this consumes no event id.
            return event_id, REJECTED, INVALID_SCHEMA, [], None, None, None, None, None
    # The event is well formed, so its id occupies the stream from here,
    # even if a later business rule rejects it.
    self._event_ids.add(event_id)

    if obj["type"] == CANCEL:
        event_id, result, reason, trades = self._cancel(event_id, obj["order_id"])
        return event_id, result, reason, trades, None, None, None, None, None
    if obj["type"] == REPLACE:
        event_id, result, reason, trades, stp = self._replace(event_id, obj)
        return event_id, result, reason, trades, stp, None, None, None, None
    if obj["type"] == EXECUTION_REPORT:
        event_id, result, reason, trades, stp, analysis = self._execution_report(
            event_id, obj
        )
        return event_id, result, reason, trades, stp, analysis, None, None, None
    if obj["type"] == IMPACT_REPORT:
        event_id, result, reason, trades, impact = self._impact_report(
            event_id, obj
        )
        return event_id, result, reason, trades, None, None, None, None, impact
    if obj["type"] == ACCOUNT_REPORT:
        event_id, result, reason, trades, stp, analysis, position = (
            self._account_report(event_id, obj)
        )
        return event_id, result, reason, trades, stp, analysis, position, None, None
    if obj["type"] == DAY_END_RECONCILIATION:
        return (*self._day_end_reconciliation(event_id, obj), None)
    event_id, result, reason, trades, stp = self._add(event_id, obj)
    return event_id, result, reason, trades, stp, None, None, None, None

@staticmethod
def _schema_error(obj: dict[str, object]) -> str | None:

"""Single-document JSON entry point for ordered multi-symbol event replay.

The command reads exactly one UTF-8 JSON request document from standard
input and writes exactly one UTF-8 JSON response document to standard
output. It never opens files; snapshots and results only travel through the
caller-supplied document.
"""

from __future__ import annotations

import json
import sys

from .event_replay import (
    SnapshotError,
    canonical_json,
    replay_events,
)

_ERROR_IO = "ERROR_IO\n"
_INVALID_REQUEST = "INVALID_REQUEST"


def _write_error(stdout: object, stderr: object, code: str, message: str) -> int:
    try:
        stdout.buffer.write(
            canonical_json({"error": {"code": code, "message": message}}) + b"\n"
        )
        stdout.buffer.flush()
    except OSError:
        try:
            stderr.write(_ERROR_IO)
            stderr.flush()
        except OSError:
            pass
        return 1
    return 2


def serve_events(
    stdin: object = sys.stdin,
    stdout: object = sys.stdout,
    stderr: object = sys.stderr,
) -> int:
    """Run one events request. Returns the process exit code."""
    try:
        raw = stdin.buffer.read()
        text = raw.decode("utf-8")
    except (OSError, UnicodeError):
        try:
            stderr.write(_ERROR_IO)
            stderr.flush()
        except OSError:
            pass
        return 1

    try:
        request = json.loads(text)
    except json.JSONDecodeError:
        return _write_error(stdout, stderr, _INVALID_REQUEST, "request must be one JSON document")
    if (
        not isinstance(request, dict)
        or not isinstance(request.get("events"), list)
        or not set(request) <= {"events", "config", "snapshot", "snapshot_after"}
        or (
            "config" in request
            and not isinstance(request["config"], dict)
        )
        or (
            "snapshot" in request
            and request["snapshot"] is not None
            and not isinstance(request["snapshot"], dict)
        )
    ):
        return _write_error(
            stdout, stderr, _INVALID_REQUEST,
            'request must be an object with an "events" list and optional '
            '"config" and "snapshot" objects',
        )

    marker = request.get("snapshot_after", "last")
    if marker is not None and marker != "last":
        if not (
            isinstance(marker, dict)
            and isinstance(marker.get("symbol"), str)
            and isinstance(marker.get("sequence"), int)
        ):
            return _write_error(
                stdout, stderr, _INVALID_REQUEST,
                'snapshot_after must be "last", null or '
                '{"symbol": str, "sequence": int}',
            )

    try:
        response = replay_events(
            request["events"],
            config=request.get("config"),
            snapshot=request.get("snapshot"),
            snapshot_after=marker,
        )
    except SnapshotError as exc:
        return _write_error(stdout, stderr, exc.code, str(exc))
    except (TypeError, ValueError) as exc:
        return _write_error(stdout, stderr, _INVALID_REQUEST, str(exc))

    try:
        stdout.buffer.write(canonical_json(response) + b"\n")
        stdout.buffer.flush()
    except OSError:
        try:
            stderr.write(_ERROR_IO)
            stderr.flush()
        except OSError:
            pass
        return 1
    return 0

"""JSON Lines event replay over standard input/output.

Each non-empty input line is handled in order and produces one JSON object
on standard output. Empty lines are ignored. The program never opens any
files itself.
"""

from __future__ import annotations

import json
import sys

from .engine import Engine

_ERROR_IO = "ERROR_IO\n"


def _encode(payload: dict[str, object]) -> bytes:
    return json.dumps(payload, ensure_ascii=False, separators=(",", ":")).encode("utf-8")


def replay(stdin: object = sys.stdin, stdout: object = sys.stdout, stderr: object = sys.stderr) -> int:
    """Run the replay loop. Returns the process exit code."""
    engine = Engine()
    out_parts: list[bytes] = []

    try:
        raw = stdin.buffer.read()
        text = raw.decode("utf-8")
    except (OSError, UnicodeError):
        try:
            stderr.write(_ERROR_IO)
            stderr.flush()
        except OSError:
            pass
        return 1

    for line in text.split("\n"):
        if line.endswith("\r"):
            line = line[:-1]
        if line == "":
            continue

        event_id, result, reason, trades, stp, analysis, position, reconciliation, impact = (
            engine.handle_line_impact(line)
        )
        bids, asks = engine.snapshot()
        payload: dict[str, object] = {
            "input_line": line,
            "event_id": event_id,
            "result": result,
        }
        if reason is not None:
            payload["reason"] = reason
        if stp is not None:
            payload["self_trade_prevention"] = stp
        if analysis is not None:
            payload["execution_analysis"] = analysis
        if position is not None:
            payload["position_analysis"] = position
        if reconciliation is not None:
            payload["reconciliation"] = reconciliation
        if impact is not None:
            payload["impact_analysis"] = impact
        payload["trades"] = trades
        payload["bids"] = bids
        payload["asks"] = asks
        out_parts.append(_encode(payload))
        out_parts.append(b"\n")

    try:
        stdout.buffer.write(b"".join(out_parts))
        stdout.buffer.flush()
    except OSError:
        try:
            stderr.write(_ERROR_IO)
            stderr.flush()
        except OSError:
            pass
        return 1
    return 0

